commands.cmd:
{
  env -i PATH="$PATH" HOME="$HOME" TMPDIR="${TMPDIR:-/tmp}" bash tests/test-setup.sh
  env -i PATH="$PATH" HOME="$HOME" TMPDIR="${TMPDIR:-/tmp}" bash tests/test-detached-dispatch.sh
} >.singular-evidence/green.log 2>&1

{
  env -i PATH="$PATH" HOME="$HOME" TMPDIR="${TMPDIR:-/tmp}" bash tests/test-versioning.sh
  env -i PATH="$PATH" HOME="$HOME" TMPDIR="${TMPDIR:-/tmp}" bash tests/test-cli-test-run.sh
  env -i PATH="$PATH" HOME="$HOME" TMPDIR="${TMPDIR:-/tmp}" bash tests/test-reap-classification.sh
} >.singular-evidence/direct-regression.log 2>&1

bash -n tests/test-setup.sh tests/test-detached-dispatch.sh
fixture_leaks="$(find "${TMPDIR:-/tmp}" -maxdepth 6 -path '*/repo/.singular-state/fixture-workers/*/started' -print 2>/dev/null | wc -l | tr -d ' ')"
[[ "$fixture_leaks" == "0" ]] || { printf 'fixture worker marker leaks: %s\n' "$fixture_leaks" >&2; exit 1; }
